namespace AfriWallet.Fraud.DeviceRisk.Domain.Models;
public sealed class DeviceAccountRiskProfile{public DeviceAccountRiskProfile(Guid id,string awid,string deviceId,int score,RiskBand band,RiskRecommendation recommendation,IReadOnlyCollection<DeviceRiskFactor> factors,DateTimeOffset at){if(id==Guid.Empty)throw new ArgumentException("Profile id is required.");if(string.IsNullOrWhiteSpace(awid))throw new ArgumentException("AWID is required.");if(string.IsNullOrWhiteSpace(deviceId))throw new ArgumentException("Device id is required.");ProfileId=id;Awid=awid.Trim();DeviceId=deviceId.Trim();Score=Math.Clamp(score,0,100);Band=band;Recommendation=recommendation;Factors=factors;CalculatedAtUtc=at;}public Guid ProfileId{get;}public string Awid{get;}public string DeviceId{get;}public int Score{get;}public RiskBand Band{get;}public RiskRecommendation Recommendation{get;}public IReadOnlyCollection<DeviceRiskFactor> Factors{get;}public DateTimeOffset CalculatedAtUtc{get;}}